def feats(s):
    h,w=len(s),len(s[0]); n=sum(map(sum,s))
    # holes: bg cells not reachable from bbox border (4-conn)
    bg={(i,j) for i in range(h) for j in range(w) if not s[i][j]}
    seen=set()
    for i in range(h):
        for j in range(w):
            if not s[i][j] and (i in(0,h-1) or j in(0,w-1)) and (i,j) not in seen:
                q=collections.deque([(i,j)]); seen.add((i,j))
                while q:
                    y,x=q.popleft()
                    for dy,dx in((1,0),(-1,0),(0,1),(0,-1)):
                        a,b=y+dy,x+dx
                        if (a,b) in bg and (a,b) not in seen: seen.add((a,b)); q.append((a,b))
    holes=len(bg-seen)
    # perimeter (4-conn edges)
    per=0
    for i in range(h):
        for j in range(w):
            if s[i][j]: per+=sum(1 for dy,dx in((1,0),(-1,0),(0,1),(0,-1)) if not (0<=i+dy<h and 0<=j+dx<w and s[i+dy][j+dx]))
