    def sym180(k): return json.dumps(k)==json.dumps([r[::-1] for r in k[::-1]])
    def symt(k):
        t=[list(r) for r in zip(*k)]
        return json.dumps(k)==json.dumps(t)
    return dict(h=h,w=w,n=n,holes=holes,per=per,symLR=sym(s),symUD=symv(s),sym180=sym180(s),symT=symt(s))
